USE CATALOG IDENTIFIER(:catalog);

-- sessionization: Redshift DATEDIFF(second) counts second boundaries crossed,
-- so truncate both sides to the second before timestampdiff.
CREATE OR REPLACE TABLE gold.web_sessions
CLUSTER BY (customer_id, session_id)
AS
WITH lagged AS (
    SELECT customer_id,
           event_id,
           event_ts,
           event_type,
           LAG(event_ts) OVER (PARTITION BY customer_id
                               ORDER BY event_ts NULLS LAST, event_id NULLS LAST) AS prev_ts
    FROM   silver.web_events
    WHERE  customer_id IS NOT NULL
),
flagged AS (
    SELECT customer_id,
           event_id,
           event_ts,
           event_type,
           CASE
             WHEN prev_ts IS NULL THEN 1
             WHEN timestampdiff(SECOND, date_trunc('SECOND', prev_ts),
                                date_trunc('SECOND', event_ts)) > 1800 THEN 1
             ELSE 0
           END AS new_session
    FROM   lagged
),
numbered AS (
    SELECT customer_id,
           event_id,
           event_ts,
           event_type,
           SUM(new_session) OVER (PARTITION BY customer_id
                                  ORDER BY event_ts NULLS LAST, event_id NULLS LAST
                                  ROWS UNBOUNDED PRECEDING) AS session_id
    FROM   flagged
)
SELECT customer_id,
       session_id,
       MIN(event_ts)      AS session_start_ts,
       MAX(event_ts)      AS session_end_ts,
       COUNT(*)           AS event_count,
       SUM(CASE WHEN event_type = 'checkout' THEN 1 ELSE 0 END) AS checkout_events
FROM   numbered
GROUP  BY customer_id, session_id;
